import os,re,json
from collections import deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read(); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def solve(g):
    h,w=len(g),len(g[0]); o=[r[:] for r in g]; bg=g[0][0]
    cs=set(x for r in g for x in r); cs.discard(bg)
    for c in sorted(cs,key=lambda c:-g.count(c)):
        pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]==c]
        mi=min(i for i,_ in pts); mx=max(i for i,_ in pts); mj=min(j for _,j in pts); Mx=max(j for _,j in pts)
        if len(pts)<8 or mi==mx or mj==Mx: continue
        # interior non-c cells reachable from... enclosed means not connected to outside through non-c
        # BFS over non-c cells starting from all non-c cells on grid border; interior = non-c not reached
        seen=[[False]*w for _ in range(h)]
        q=deque()
        for i in range(h):
            for j in (0,w-1):
                if g[i][j]!=c and not seen[i][j]: seen[i][j]=True; q.append((i,j))
        for j in range(w):
            for i in (0,h-1):
                if g[i][j]!=c and not seen[i][j]: seen[i][j]=True; q.append((i,j))
        while q:
            i,j=q.popleft()
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni,nj=i+di,j+dj
                if 0<=ni<h and 0<=nj<w and g[ni][nj]!=c and not seen[ni][nj]:
                    seen[ni][nj]=True; q.append((ni,nj))
        inside=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=c and not seen[i][j]]
        if inside:
            fill=7 if c!=1 else 2
            for i,j in inside: o[i][j]=fill
    return o
